-- Green Meadows society database: schema and sample data (synthetic)
CREATE TABLE building (building_id INT PRIMARY KEY, name VARCHAR(60) NOT NULL, total_floors INT);
CREATE TABLE apartment (apartment_id INT PRIMARY KEY, building_id INT NOT NULL REFERENCES building(building_id), unit_number VARCHAR(10) NOT NULL, floor INT, area_sqft INT, type VARCHAR(10));
CREATE TABLE resident (resident_id INT PRIMARY KEY, full_name VARCHAR(80) NOT NULL, phone VARCHAR(15), email VARCHAR(80));
CREATE TABLE occupancy (occupancy_id INT PRIMARY KEY, apartment_id INT NOT NULL REFERENCES apartment(apartment_id), resident_id INT NOT NULL REFERENCES resident(resident_id), type VARCHAR(10) CHECK (type IN ('owner','tenant')), start_date DATE, end_date DATE);
CREATE TABLE staff (staff_id INT PRIMARY KEY, name VARCHAR(80) NOT NULL, role VARCHAR(30), phone VARCHAR(15), joined_on DATE);
CREATE TABLE service_request (request_id INT PRIMARY KEY, apartment_id INT NOT NULL REFERENCES apartment(apartment_id), resident_id INT REFERENCES resident(resident_id), staff_id INT REFERENCES staff(staff_id), category VARCHAR(30), description VARCHAR(200), status VARCHAR(15), raised_at TIMESTAMP, resolved_at TIMESTAMP);
CREATE TABLE maintenance_bill (bill_id INT PRIMARY KEY, apartment_id INT NOT NULL REFERENCES apartment(apartment_id), billing_month CHAR(7), base_amount DECIMAL(10,2), late_fee DECIMAL(10,2), total_amount DECIMAL(10,2), due_date DATE, status VARCHAR(10));
CREATE TABLE payment (payment_id INT PRIMARY KEY, bill_id INT NOT NULL REFERENCES maintenance_bill(bill_id), resident_id INT REFERENCES resident(resident_id), amount_paid DECIMAL(10,2), paid_on DATE, mode VARCHAR(15));
CREATE TABLE visitor (visitor_id INT PRIMARY KEY, name VARCHAR(80), phone VARCHAR(15), id_proof_type VARCHAR(20), id_last4 CHAR(4));
CREATE TABLE visit_log (visit_id INT PRIMARY KEY, visitor_id INT NOT NULL REFERENCES visitor(visitor_id), apartment_id INT NOT NULL REFERENCES apartment(apartment_id), staff_id INT REFERENCES staff(staff_id), purpose VARCHAR(20), check_in TIMESTAMP, check_out TIMESTAMP);

